#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    long n;
    char *endptr;

    /* No argument supplied */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Convert the argument to a long (base 10) */
    errno = 0;
    n = strtol(argv[1], &endptr, 10);

    /* Invalid integer (no characters consumed or trailing chars) */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Range checks */
    if (n < 1) {               // numbers <= 0 are considered bad input
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000) {         // upper bound enforced by the original program
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Compute the sum of proper divisors of n (excluding n itself) */
    long sum = 0;
    for (long d = 1; d * d <= n; ++d) {
        if (n % d == 0) {
            long other = n / d;
            if (d != n)               sum += d;               // d is a proper divisor
            if (other != d && other != n) sum += other;        // paired divisor
        }
    }

    /* Classification output */
    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum > n) {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    } else {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    }

    return 0;
}
